import{z as o,x as i,o as B,c as p,q as r,j as l,D as A,d as a,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"可观测性","description":"","frontmatter":{"title":"可观测性","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/agent-observability.md","filePath":"llm/agent-observability.md","lastUpdated":1791413859000}'),C={name:"llm/agent-observability.md"};function d(m,E,F,c,D,h){const t=i("Mermaid");return B(),p("div",null,[E[2]||(E[2]=r('<h1 id="可观测性" tabindex="-1">可观测性 <a class="header-anchor" href="#可观测性" aria-label="Permalink to &quot;可观测性&quot;">​</a></h1><div class="epigraph"><p>服务可观测的对象是请求，代理可观测的对象是轨迹；少了带版本标注的轨迹账本，调试靠猜，回滚靠赌。</p><footer>—— 据 OpenTelemetry GenAI 语义约定（草案口径）与部署后监控的工程实践整理</footer></div><p><a href="/llm/agent-guardrails">上一课</a>的围栏要调平衡、<a href="/llm/agent-cost-latency">成本与延迟优化</a>的账要审、后续回归要放样——三件事依赖同一件基础设施：每条轨迹被完整、带版本地记录下来。主干已有<a href="/llm/deployment-monitoring">部署后监控</a>讲流量抽检与漂移、<a href="/llm/serving-metrics">服务指标 TTFT / TPOT / 吞吐</a>讲单次调用的指标；本课把观测对象升级为轨迹：一次任务的完整因果树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>观测不足的症状都很具体。线上失败无法归因：用户说「它把订单发错了」，你查不到那条轨迹死在哪一步、当时模型看到什么。成本对不上账：月账单除以任务数得到的均值毫无用处，长尾几条轨迹占了半数成本。<span class="marginnote">「长尾」的数字实例：假设 9900 个任务每个花 3 分钱，剩下 100 个任务因为反复重试每个花 30 块，总账约 3297 元、均值 3 毛 3——但均值既不代表普通任务，也说不出钱烧在哪 100 条轨迹上，所以必须按任务粒度记账。</span>围栏误杀无法复盘：拦截发生时若没存下完整输入，误杀与正确拦截永远分不清。回归没有靶子：想在新版本上重放上周的真实失败，却发现当时的 prompt 与工具清单没有版本标注，重放无从谈起。根因都一样：代理的可观测单元不是 HTTP 请求，而是「任务」——树状的因果结构，缺一处标注，整棵树就断了证据链。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>数据模型</strong>：trace 对应一次任务，span 对应一次模型调用、工具调用或子代理<span class="marginnote">trace 和 span 借自分布式追踪（OpenTelemetry）：span 是一次可计时的操作单元，像简历上的一行经历；trace 是整份简历——把一次任务里的所有 span 按父子关系串成的完整故事。父子的连线就是「谁触发了谁」，即因果。</span>；父子关系即因果，重试是兄弟 span，恢复动作单独标记（<a href="/llm/agent-error-recovery">错误恢复与重试</a>的四级失败直接成为 span 的分类字段）。<strong>版本标注</strong>：每个 span 记模型版本、系统提示版本、工具清单哈希、编排代码版本——这是轨迹能跨版本比较的前提，也是下一课回归测试的原材料。<strong>记录内容</strong>：完整的输入输出（含每步模型看到的确切上下文）、工具参数与结果、每步耗时与 token、结束语义（声明完成/预算/门禁）、围栏事件。<strong>在线指标</strong>：任务完成率、人工接管率、每步失败率分布、预算耗尽占比、围栏拦截与误杀、按任务的 token 与费用分位数。<strong>抽样审计</strong>：全量人审不可能，用 LLM 裁判初筛，但裁判偏差要先校准（<a href="/llm/llm-judge-bias">LLM 裁判偏差</a>），裁判否决的轨迹进人工队列。</p>',7)),(B(),l(s,null,{default:A(()=>[n(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22trace%EF%BC%9A%E4%B8%80%E6%AC%A1%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20S1%5B%22span%EF%BC%9A%E6%A8%A1%E5%9E%8B%E8%B0%83%E7%94%A8%EF%BC%88%E7%89%88%E6%9C%AC%E6%A0%87%E6%B3%A8%EF%BC%89%22%5D%0A%20%20T%20--%3E%20S2%5B%22span%EF%BC%9A%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%EF%BC%88%E5%8F%82%E6%95%B0%E4%B8%8E%E7%BB%93%E6%9E%9C%EF%BC%89%22%5D%0A%20%20T%20--%3E%20S3%5B%22span%EF%BC%9A%E5%AD%90%E4%BB%A3%E7%90%86%EF%BC%88%E5%B5%8C%E5%A5%97%20trace%EF%BC%89%22%5D%0A%20%20S1%20--%3E%20M%5B%22%E5%9C%A8%E7%BA%BF%E6%8C%87%E6%A0%87%EF%BC%9A%E5%AE%8C%E6%88%90%E7%8E%87%E3%80%81%E6%8E%A5%E7%AE%A1%E7%8E%87%E3%80%81%E5%A4%B1%E8%B4%A5%E5%88%86%E5%B8%83%22%5D%0A%20%20S2%20--%3E%20M%0A%20%20S3%20--%3E%20M%0A%20%20M%20--%3E%20AL%7B%22%E8%B6%8A%E9%98%88%E5%80%BC%E6%88%96%E5%BC%82%E5%B8%B8%3F%22%7D%0A%20%20AL%20--%3E%7C%22%E6%98%AF%22%7C%20ALERT%5B%22%E5%91%8A%E8%AD%A6%20%2B%20%E8%BD%A8%E8%BF%B9%E8%BF%9B%E4%BA%BA%E5%B7%A5%E9%98%9F%E5%88%97%22%5D%0A%20%20AL%20--%3E%7C%22%E5%90%A6%22%7C%20STORE%5B%22%E8%84%B1%E6%95%8F%E5%BD%92%E6%A1%A3%EF%BC%9A%E5%B8%A6%E4%BF%9D%E7%95%99%E6%9C%9F%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("为什么按因果树而不是日志行存：归因查询「死在门禁的轨迹里，上一步是什么」在树结构上是一次遍历，在平铺日志上是全表扫描加人工拼接——数据形状决定排障速度。为什么版本标注是第一字段：轨迹的每一条结论（这个版本失败率高、这次误杀是提示的锅）都是"),e("strong",null,"关于某个版本组合"),a("的陈述，没有标注的轨迹只能讲故事不能下结论。记录与合规的张力用两层解：入库前脱敏（"),e("a",{href:"/llm/pii-redact"},"PII 脱敏"),a("）划掉可以划掉的字段，保留期与访问控制管理剩下的；「完整记录」与「最小留存」的平衡点按业务的风险等级定，不追求一步到位。")],-1)),(B(),l(s,null,{default:A(()=>[n(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22trace%EF%BC%9A%E4%B8%80%E6%AC%A1%E5%A4%B1%E8%B4%A5%E7%9A%84%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20B%5B%22span%EF%BC%9A%E6%A8%A1%E5%9E%8B%E8%B0%83%E7%94%A8%EF%BC%88%E5%B8%A6%E7%89%88%E6%9C%AC%E6%A0%87%E6%B3%A8%EF%BC%89%22%5D%0A%20%20B%20--%3E%20C%5B%22span%EF%BC%9A%E5%B7%A5%E5%85%B7%E8%B0%83%E7%94%A8%20%E5%8F%91%E5%87%BA%E8%AE%A2%E5%8D%95%22%5D%0A%20%20C%20--%3E%20D%5B%22span%EF%BC%9A%E9%97%A8%E7%A6%81%E6%8B%A6%E6%88%AA%EF%BC%88%E7%BB%93%E6%9D%9F%E8%AF%AD%E4%B9%89%3D%E9%97%A8%E7%A6%81%EF%BC%89%22%5D%0A%20%20D%20--%3E%20E%5B%22%E9%87%8D%E6%94%BE%EF%BC%9A%E5%90%8C%E8%BE%93%E5%85%A5%20%2B%20%E5%90%8C%E7%89%88%E6%9C%AC%E7%BB%84%E5%90%88%22%5D%0A%20%20E%20--%3E%20F%7B%22%E5%A4%B1%E8%B4%A5%E5%A4%8D%E7%8E%B0%3F%22%7D%0A%20%20F%20--%3E%7C%22%E6%98%AF%22%7C%20G%5B%22%E5%BD%92%E5%9B%A0%E5%88%B0%E6%8F%90%E7%A4%BA%E6%88%96%E6%A8%A1%E5%9E%8B%E7%89%88%E6%9C%AC%22%5D%0A%20%20F%20--%3E%7C%22%E5%90%A6%22%7C%20H%5B%22%E5%BD%92%E5%9B%A0%E5%88%B0%E7%8E%AF%E5%A2%83%E6%88%96%E6%95%B0%E6%8D%AE%E5%B7%AE%E5%BC%82%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">一次模型调用的 span 要存「模型看到的确切内容」，不是「应用拼装的模板」：聊天模板渲染、截断与压缩发生在请求前——只存模板，回放时模型看到的可能已经不同，轨迹就成了不可复现的证据。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>观测不改变行为，只还原行为；把在线指标当优化目标会引入古德哈特效应<span class="marginnote">古德哈特定律：一个指标一旦被当成考核目标，它就不再可靠。放到代理上：把「任务完成率」直接挂进奖励，模型可能学会「提前声明完成」来刷指标——数字变好了，实际活没干成，这正是观测必须与优化分离的原因。</span>——指标进奖励的问题在<a href="/llm/agent-eval-success-process">评测：任务成功率与过程</a>已经警告过。全量记录有成本：token 详单、存储与查询都按量计费，采样策略（全量存失败与围栏事件、按比例存成功）是常规解。轨迹账本是下一课的输入：回归测试的重放集、回滚的触发证据都从这里来；与<a href="/llm/deployment-monitoring">部署后监控</a>的分工是——监控回答「线上现在怎么样」，轨迹账本回答「为什么」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>观测单元从请求升级为轨迹：trace 为根、span 为节点、父子即因果。</li><li>版本标注是第一字段：模型、提示、工具清单、编排代码缺一不可。</li><li>结束语义与失败分级作为 span 字段，归因查询才能自动化。</li><li>LLM 裁判初筛要校准偏差，否决轨迹进人工队列。</li><li>脱敏与保留期在入库前定；存「模型看到的确切内容」才可回放。</li><li>出处：据 OpenTelemetry GenAI 语义约定草案与部署监控实践整理，非单篇论文口径。</li></ul>',5))])}const T=o(C,[["render",d]]);export{f as __pageData,T as default};
